import{_ as e,o as r,c as a,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-03-15","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-03-15","date":"2022-03-15T00:00:00.000Z","updated":"2022-03-18T00:00:00.000Z","tags":["Ceph","Orchestrator","防火墙管理","监控配置","代码结构"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-03-15.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-03-15.md","lastUpdated":1780460162000}'),o={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-03-15.md"};function i(s,t,n,h,p,g){return r(),a("div",null,[...t[0]||(t[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-防火墙管理与ceph配置" tabindex="-1">会议主题：防火墙管理与Ceph配置 <a class="header-anchor" href="#会议主题-防火墙管理与ceph配置" aria-label="Permalink to &quot;会议主题：防火墙管理与Ceph配置&quot;">​</a></h4><p><strong>讨论内容：</strong></p><ul><li><strong>防火墙管理</strong>：会议重点讨论了Ceph防火墙管理的现状和未来。主要围绕是否应该移除防火墙配置的标记（flag），以及是否应该在启动时进行防火墙配置进行了深入讨论。</li><li><strong>历史背景</strong>：标记和相关代码已被移除，原计划的重构未实施。目前，Ceph不再处理防火墙相关事务。</li><li><strong>用户需求</strong>：虽有下游用户询问过此功能，但需求并不强烈。</li><li><strong>决策</strong>：会议决定不重新引入防火墙管理功能，而是选择隐藏该标记，以避免影响现有脚本，并防止新用户误用。</li></ul><p><strong>后续行动：</strong></p><ul><li>隐藏防火墙管理相关的标记。</li><li>继续监控用户对此功能的需求，根据反馈决定是否重新考虑实施防火墙管理。</li></ul><h4 id="会议主题-新功能开发-外部监控配置报告" tabindex="-1">会议主题：新功能开发 - 外部监控配置报告 <a class="header-anchor" href="#会议主题-新功能开发-外部监控配置报告" aria-label="Permalink to &quot;会议主题：新功能开发 - 外部监控配置报告&quot;">​</a></h4><p><strong>讨论内容：</strong></p><ul><li><strong>功能需求</strong>：开发一个新功能，允许Ceph Admin (cf-admin) 报告已部署服务的不同配置，如机器颜色管理器、节点导出器、HA代理等。</li><li><strong>实施计划</strong>：通过在代理中添加新的端点，利用Prometheus的新特性动态获取这些配置，而不是使用静态信息。</li><li><strong>当前进展</strong>：已经开始实施，预计在完成初步开发后进行代码审查和分享。</li></ul><p><strong>后续行动：</strong></p><ul><li>继续开发并实现新端点，确保与Prometheus的集成。</li><li>修改监控类以使用这些新端点动态生成配置文件。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li><strong>代码结构问题</strong>：讨论了Ceph管理模块的代码结构问题，特别是Python和C++部分的交互。虽然目前不需要改变，但提出了未来可能需要的技术支持和资源问题。</li></ul><p><strong>后续行动：</strong></p><ul><li>继续监控和评估代码结构，必要时寻求社区资源支持。</li></ul><h4 id="会议总结" tabindex="-1">会议总结 <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结&quot;">​</a></h4><ul><li>本次会议主要解决了防火墙管理标记的处理问题，并讨论了新功能开发的进展和计划。</li><li>对于代码结构和未来可能的技术挑战，提出了关注和准备。</li></ul><p><strong>下次会议预告：</strong></p><ul><li>预计在接下来的会议中继续讨论新功能的实施细节和可能遇到的技术难题。</li></ul><p><strong>会议结束：</strong></p><ul><li>会议在确认无其他议题后结束，下次会议再见。</li></ul>',21)])])}const d=e(o,[["render",i]]);export{c as __pageData,d as default};
